css:
.deanbet-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2238;
    background: linear-gradient(160deg, #f3f1ec 0%, #eae7df 100%);
    border-radius: 18px;
}

.deanbet-container * {
    box-sizing: border-box;
}

.deanbet-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #14213d 0%, #283655 55%, #3a4a73 100%);
    color: #f6f4ee;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(20, 33, 61, 0.32);
    border-bottom: 4px solid #c39b3a;
}

.deanbet-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.deanbet-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e7cf94;
    background: rgba(195, 155, 58, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.deanbet-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e3e0d6;
}

.deanbet-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #283655;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.deanbet-period-counter #currentDay,
.deanbet-period-counter #maxPeriods {
    font-weight: 800;
    color: #14213d;
}

.deanbet-round-name {
    background: #dcd6c5;
    color: #5a4715;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.deanbet-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a3324;
    background: #f2dcd6;
    padding: 4px 12px;
    border-radius: 999px;
}

.deanbet-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.deanbet-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #ddd6c8;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.07);
    border-top: 4px solid #3a4a73;
}

.deanbet-card-diff { border-top-color: #c39b3a; }
.deanbet-card-rank { border-top-color: #2f6fb0; }
.deanbet-card-surplus { border-top-color: #1f8a5b; }
.deanbet-card-balance { border-top-color: #7a4fb0; }

.deanbet-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a6450;
}

.deanbet-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14213d;
}

.deanbet-card-diff .deanbet-value { color: #a67c12; }
.deanbet-card-rank .deanbet-value { color: #2f6fb0; }
.deanbet-card-surplus .deanbet-value { color: #1f8a5b; }
.deanbet-card-balance .deanbet-value { color: #7a4fb0; }

.deanbet-sublabel {
    font-size: 0.76rem;
    color: #837c66;
    line-height: 1.35;
}

.deanbet-surplus-breach .deanbet-value { color: #c0392b; }
.deanbet-surplus-breach { border-top-color: #c0392b; }
.deanbet-balance-strong .deanbet-value { color: #1f8a5b; }

.deanbet-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #14213d;
    color: #f1eee5;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 4px solid #c39b3a;
}

.deanbet-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e7cf94;
}

.deanbet-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c39b3a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.05);
}

.deanbet-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.deanbet-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14213d;
    margin-bottom: 6px;
}

.deanbet-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2f3550;
}

.deanbet-briefing-text strong { color: #1f8a5b; }
.deanbet-briefing-text em { color: #8a3324; font-style: italic; }

.deanbet-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ddd6c8;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.07);
}

.deanbet-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14213d;
    border-bottom: 2px solid #ece8dd;
    padding-bottom: 8px;
}

.deanbet-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #232a44;
    margin: 14px 0 6px;
}

.deanbet-container select,
.deanbet-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cabf9f;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf8f2;
    color: #1c2238;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.deanbet-container select:focus,
.deanbet-container input[type="number"]:focus {
    outline: none;
    border-color: #c39b3a;
    box-shadow: 0 0 0 3px rgba(195, 155, 58, 0.18);
}

.deanbet-container select option {
    background-color: #ffffff;
    color: #1c2238;
}

.deanbet-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c39b3a;
}

.deanbet-range-readout,
.deanbet-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #283655;
    margin-top: 4px;
}

.deanbet-range-readout span:last-child,
.deanbet-alloc-readout span:nth-child(2) {
    color: #a67c12;
    font-weight: 800;
}

.deanbet-hint {
    font-size: 0.8rem;
    color: #837c66;
    margin-top: 4px;
    line-height: 1.4;
}

.deanbet-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.deanbet-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f4ec;
    border: 1px solid #e4ddca;
    border-radius: 9px;
    padding: 8px 12px;
}

.deanbet-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #232a44;
}

.deanbet-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.deanbet-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.deanbet-container .btn-primary {
    background: linear-gradient(135deg, #14213d 0%, #3a4a73 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(20, 33, 61, 0.30);
    color: #fdfbf4;
}

.deanbet-container .btn-primary:hover {
    filter: brightness(1.12);
}

.deanbet-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cabf9f;
    color: #6a6450;
}

.deanbet-coach {
    background: #14213d;
    color: #ece9df;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 33, 61, 0.24);
    border-left: 4px solid #c39b3a;
}

.deanbet-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7cf94;
    margin-bottom: 8px;
}

.deanbet-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.deanbet-coach-body strong { color: #f0d68a; }
.deanbet-coach-body em { color: #f2b39d; font-style: italic; }

.deanbet-history,
.deanbet-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ddd6c8;
    box-shadow: 0 4px 14px rgba(20, 33, 61, 0.07);
}

.deanbet-history h3,
.deanbet-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14213d;
}

.deanbet-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #232a44;
}

.deanbet-container table#usfHistoryTable th {
    background: #efebe0;
    color: #14213d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd6c8;
}

.deanbet-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ede4;
}

.deanbet-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f2;
}

.deanbet-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .deanbet-container {
        padding: 14px;
    }
    .deanbet-header h1 {
        font-size: 1.7rem;
    }
    .deanbet-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .deanbet-value {
        font-size: 2rem;
    }
    .deanbet-clock {
        margin-left: 0;
    }
    .deanbet-period-counter {
        font-size: 0.88rem;
    }
    .deanbet-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .deanbet-alloc-row {
        flex-wrap: wrap;
    }
    .deanbet-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .deanbet-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion-message card (appended; self-contained, navy/gold) */
.deanbet-cm { background:#f7f4ec; color:#14213d; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(20,33,61,0.22); }
.deanbet-cm-head { text-align:center; border-bottom:1px solid #ddd6c8; padding-bottom:14px; margin-bottom:16px; }
.deanbet-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#9a7a24; font-weight:700; }
.deanbet-cm-scorewrap { margin:8px 0 2px; }
.deanbet-cm-score { font-size:52px; font-weight:800; color:#14213d; line-height:1; }
.deanbet-cm-score-max { font-size:20px; color:#8a8676; font-weight:600; }
.deanbet-cm-grade { font-size:19px; font-weight:700; color:#14213d; margin-top:4px; }
.deanbet-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.deanbet-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.deanbet-cm-met { background:#cfe8d8; color:#136b45; }
.deanbet-cm-fail { background:#f1dcd6; color:#9c3a2b; }
.deanbet-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.deanbet-cm-metric { background:#efe9db; border-radius:10px; padding:12px 16px; min-width:96px; text-align:center; }
.deanbet-cm-metric-val { font-size:22px; font-weight:800; color:#14213d; }
.deanbet-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#9a7a24; margin-top:3px; }
.deanbet-cm-insights { background:#efe9db; border-radius:10px; padding:14px 18px; }
.deanbet-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#9a7a24; font-weight:700; margin-bottom:8px; }
.deanbet-cm-insights ul { margin:0; padding-left:18px; }
.deanbet-cm-insights li { font-size:14px; line-height:1.5; color:#2b2f3d; margin-bottom:7px; }

