(function() {
    'use strict';

    class DeanBetAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Dean's Bet`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.ENVELOPE = 14.0;            // EUR 14M envelope over 3 years
            this.ASKS_TOTAL = 31.0;          // ~EUR 31M of credible asks
            this.START_DIFF = 30;            // differentiation / brand-moat strength
            this.START_RANK = 35;            // reputation index — 41st today
            this.START_SURPLUS = 3.9;        // operating surplus % today
            this.SURPLUS_FLOOR = 2.0;        // development-loan covenant floor
            this.START_BALANCE = 25;         // portfolio balance — a real bet vs spread thin

            // Targets (reachable by a legitimate concept-correct play; verified by trace).
            this.TARGET_DIFF = 62;
            this.TARGET_RANK = 52;
            this.TARGET_BALANCE = 60;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    diff: this.START_DIFF,
                    rank: this.START_RANK,
                    surplus: this.START_SURPLUS,
                    balance: this.START_BALANCE,
                    budgetUsed: 0,
                    covenantBreached: false,
                    armsRace: false,
                    diffHistory: [this.START_DIFF],
                    rankHistory: [this.START_RANK],
                    balanceHistory: [this.START_BALANCE],
                    surplusHistory: [this.START_SURPLUS],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults = a MIDDLING / neutral mix, NOT the textbook-correct play.
                state.decisions = {
                    driver: `mixed`,
                    gap: `concentrate`,
                    moat: 50,
                    position: `broaden`,
                    exclude: 40,
                    link: `both`,
                    exec: 3.5,
                    degree: 4.0,
                    faculty: 4.5,
                    brand: 2.0,
                    phasing: 60,
                    stars: `one`,
                    pitch: `everyone`,
                    thin: `all_built`,
                    identity: `slogan`,
                    commit: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dr = document.getElementById(`driverInput`);
                const gp = document.getElementById(`gapInput`);
                const mo = document.getElementById(`moatInput`);
                if (dr) decisions.driver = dr.value;
                if (gp) decisions.gap = gp.value;
                if (mo) decisions.moat = parseInt(mo.value, 10);
                if (!Number.isFinite(decisions.moat) || decisions.moat < 0 || decisions.moat > 100) {
                    warn(`warn_moat_range`); return false;
                }
            } else if (round === 2) {
                const po = document.getElementById(`positionInput`);
                const ex = document.getElementById(`excludeInput`);
                const li = document.getElementById(`linkInput`);
                if (po) decisions.position = po.value;
                if (ex) decisions.exclude = parseInt(ex.value, 10);
                if (li) decisions.link = li.value;
                if (!Number.isFinite(decisions.exclude) || decisions.exclude < 0 || decisions.exclude > 100) {
                    warn(`warn_exclude_range`); return false;
                }
            } else if (round === 3) {
                const ex = document.getElementById(`execInput`);
                const de = document.getElementById(`degreeInput`);
                const fa = document.getElementById(`facultyInput`);
                const br = document.getElementById(`brandInput`);
                const ph = document.getElementById(`phasingInput`);
                const st = document.getElementById(`starsInput`);
                if (ex) decisions.exec = parseFloat(ex.value);
                if (de) decisions.degree = parseFloat(de.value);
                if (fa) decisions.faculty = parseFloat(fa.value);
                if (br) decisions.brand = parseFloat(br.value);
                if (ph) decisions.phasing = parseInt(ph.value, 10);
                if (st) decisions.stars = st.value;
                const parts = [decisions.exec, decisions.degree, decisions.faculty, decisions.brand];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.exec + decisions.degree + decisions.faculty + decisions.brand) * 10) / 10;
                if (Math.abs(total - this.ENVELOPE) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
                if (!Number.isFinite(decisions.phasing) || decisions.phasing < 20 || decisions.phasing > 90) {
                    warn(`warn_phasing_range`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const th = document.getElementById(`thinInput`);
                const id = document.getElementById(`identityInput`);
                const co = document.getElementById(`commitInput`);
                if (pi) decisions.pitch = pi.value;
                if (th) decisions.thin = th.value;
                if (id) decisions.identity = id.value;
                if (co) decisions.commit = parseInt(co.value, 10);
                if (!Number.isFinite(decisions.commit) || decisions.commit < 0 || decisions.commit > 100) {
                    warn(`warn_commit_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let diffDelta = 0, rankDelta = 0, balanceDelta = 0, surplusDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: decompose the ranking drop and quantify the portfolio gap.
                switch (d.driver) {
                    case `mixed`: diffDelta += 6; rankDelta += 4; balanceDelta += 4; coachKey = `coach_r1_mixed`; break;
                    case `money`: rankDelta += 3; diffDelta -= 6; balanceDelta -= 4; coachKey = `coach_r1_money`; break;
                    case `marketing`: diffDelta -= 8; rankDelta -= 6; coachKey = `coach_r1_marketing`; break;
                    case `noise`: rankDelta -= 10; balanceDelta -= 8; coachKey = `coach_r1_noise`; break;
                }

                // Map the asks against the envelope — concentrate vs spread vs borrow more.
                switch (d.gap) {
                    case `concentrate`: balanceDelta += 12; diffDelta += 4; if (d.driver === `mixed`) coachKey = `coach_r1_diag_sharp`; break;
                    case `spread`: balanceDelta -= 10; coachKey = `coach_r1_spread`; break;
                    case `loan`: balanceDelta -= 6; surplusDelta -= 0.6; coachKey = `coach_r1_loan`; break;
                }

                // Clarity that two funded rivals just entered the responsible-innovation space.
                if (d.moat >= 60) { diffDelta += 6; }
                else if (d.moat <= 25) { diffDelta -= 6; coachKey = `coach_r1_lowmoat`; }

                summaryKey = (d.driver === `mixed` && d.gap === `concentrate`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Set the differentiation positioning — and what MBS will NOT compete on.
                switch (d.position) {
                    case `deepen`: diffDelta += 14; balanceDelta += 6; coachKey = `coach_r2_deepen`; break;
                    case `pivot`: diffDelta += 8; rankDelta += 4; balanceDelta += 2; coachKey = `coach_r2_pivot`; break;
                    case `broaden`: diffDelta -= 8; rankDelta += 5; balanceDelta -= 4; coachKey = `coach_r2_broaden`; break;
                    case `armsrace`: diffDelta -= 14; rankDelta += 6; balanceDelta -= 8; surplusDelta -= 0.3; ds.armsRace = true; coachKey = `coach_r2_armsrace`; break;
                }

                // The "what we will NOT do" discipline.
                if (d.exclude >= 60) { diffDelta += 6; balanceDelta += 4; }
                else if (d.exclude <= 25) { diffDelta -= 6; coachKey = `coach_r2_noexclude`; }

                // Tie positioning to the ranking levers it does and does not help.
                switch (d.link) {
                    case `honest`: rankDelta += 6; diffDelta += 4; if (d.position === `deepen` || d.position === `pivot`) coachKey = `coach_r2_honest`; break;
                    case `both`: rankDelta += 2; balanceDelta -= 6; coachKey = `coach_r2_both`; break;
                    case `ignore`: diffDelta -= 6; rankDelta -= 4; coachKey = `coach_r2_ignore`; break;
                }

                summaryKey = ((d.position === `deepen` || d.position === `pivot`) && d.exclude >= 60) ? `sum_r2_good`
                    : (d.position === `armsrace` ? `sum_r2_armsrace` : `sum_r2_weak`);
            } else if (round === 3) {
                // Allocate the EUR 14M across the four pillars; phase spend; decide the stars.
                const alloc = { exec: d.exec, degree: d.degree, faculty: d.faculty, brand: d.brand };
                spend = alloc.exec + alloc.degree + alloc.faculty + alloc.brand;
                const total = spend > 0 ? spend : 1;

                // Concentration: a real bet has a clear lead pillar (Common Error 1, peanut-buttering).
                const shares = [alloc.exec / total, alloc.degree / total, alloc.faculty / total, alloc.brand / total];
                const maxShare = Math.max.apply(null, shares);
                if (maxShare >= 0.42) { balanceDelta += 14; coachKey = `coach_r3_concentrated`; }
                else if (maxShare >= 0.34) { balanceDelta += 6; }
                else { balanceDelta -= 12; coachKey = `coach_r3_peanut`; }

                // Consistency with the chosen positioning (Common Error 3, slogan-not-strategy).
                const niche = (d.position === `deepen` || d.position === `pivot`);
                const proofAssets = alloc.faculty + alloc.brand; // assets that prove a niche claim
                if (niche) {
                    if (proofAssets >= 6.0) { diffDelta += 9; balanceDelta += 4; if (maxShare >= 0.42) coachKey = `coach_r3_proves`; }
                    else if (proofAssets >= 4.0) { diffDelta += 4; }
                    else { diffDelta -= 12; coachKey = `coach_r3_slogan`; }
                    // A niche school that pours almost everything into generic degree careers contradicts itself.
                    if (alloc.degree / total >= 0.55) { diffDelta -= 8; coachKey = `coach_r3_slogan`; }
                } else if (d.position === `broaden`) {
                    // A generalist play is consistent with degree-led spend, but still needs a bet.
                    if (alloc.degree >= 5.0) { rankDelta += 6; }
                } else if (d.position === `armsrace`) {
                    // Pouring degree money into the arms race two funded rivals just entered.
                    if (alloc.degree >= 9.0) { rankDelta += 4; diffDelta -= 8; balanceDelta -= 6; coachKey = `coach_r3_armsrace`; }
                }

                // Exec-ed: fast-payback margin engine props up the surplus.
                if (alloc.exec >= 3.0) { surplusDelta += 0.7; rankDelta += 2; }
                else if (alloc.exec <= 1.0) { surplusDelta -= 0.4; coachKey = (coachKey === `coach_default`) ? `coach_r3_noexec` : coachKey; }

                // Degrees money does fix the money-fixable ranking drivers (careers, mobility).
                if (alloc.degree >= 3.0) { rankDelta += 8; }
                else if (alloc.degree >= 1.5) { rankDelta += 3; }

                // Faculty: both a cost and the reputation engine; underfunding hollows the school.
                const hollow = alloc.faculty < 2.0;

                // Phasing: front-loading Year 1 drops the surplus through the 2.0% covenant.
                // Surplus erosion scales with how much of the envelope hits Year 1.
                const year1Spend = spend * (d.phasing / 100);
                surplusDelta -= year1Spend * 0.26; // each €M front-loaded into Year 1 costs ~0.26 pts of surplus
                if (d.phasing <= 40) { balanceDelta += 4; }

                // Stars: retain both to protect chairs, reputation, EQUIS and the positioning.
                switch (d.stars) {
                    case `retain`:
                        diffDelta += 6; rankDelta += 4;
                        if (alloc.faculty < 2.5) { diffDelta -= 6; coachKey = `coach_r3_retain_underfund`; }
                        break;
                    case `one`: diffDelta += 1; break;
                    case `let_go`: diffDelta -= 14; rankDelta -= 6; coachKey = `coach_r3_hollow`; break;
                }
                if (hollow && d.stars !== `let_go`) { diffDelta -= 6; rankDelta -= 4; coachKey = `coach_r3_hollow`; }

                summaryKey = (maxShare >= 0.42 && d.phasing <= 60 && d.stars === `retain`) ? `sum_r3_good`
                    : (maxShare < 0.34 ? `sum_r3_peanut` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend the plan to the board chair and the sceptical trustee.
                switch (d.pitch) {
                    case `aligned`: diffDelta += 6; balanceDelta += 8; rankDelta += 2; coachKey = `coach_r4_aligned`; break;
                    case `climb`: rankDelta += 3; diffDelta -= 8; balanceDelta -= 6; surplusDelta -= 0.2; coachKey = `coach_r4_climb`; break;
                    case `everyone`: balanceDelta -= 12; diffDelta -= 4; coachKey = `coach_r4_everyone`; break;
                }

                switch (d.thin) {
                    case `concentrated`: balanceDelta += 12; diffDelta += 2; break;
                    case `all_built`: balanceDelta -= 8; coachKey = `coach_r4_allbuilt`; break;
                    case `more_money`: balanceDelta -= 6; coachKey = `coach_r4_moremoney`; break;
                }

                switch (d.identity) {
                    case `moat`: diffDelta += 9; balanceDelta += 2; if (d.pitch === `aligned`) coachKey = `coach_r4_moat`; break;
                    case `generalist`: diffDelta -= 10; rankDelta += 3; coachKey = `coach_r4_generalist`; break;
                    case `slogan`: diffDelta -= 12; balanceDelta -= 4; coachKey = `coach_r4_sloganpitch`; break;
                }

                // Conviction in the four KPIs nudges differentiation and balance.
                diffDelta += Math.round((d.commit - 60) / 10);
                balanceDelta += Math.round((d.commit - 60) / 12);
            }

            // Resource accounting (envelope is committed in Round 3).
            ds.budgetUsed = Math.min(this.ENVELOPE, Math.round((ds.budgetUsed + spend) * 10) / 10);

            // Apply KPI deltas with floors/caps.
            ds.diff = Math.max(0, Math.min(100, ds.diff + diffDelta));
            ds.rank = Math.max(0, Math.min(100, ds.rank + rankDelta));
            ds.balance = Math.max(0, Math.min(100, ds.balance + balanceDelta));
            ds.surplus = Math.max(-2, Math.round((ds.surplus + surplusDelta) * 10) / 10);

            // Covenant: any round whose surplus falls below 2.0% trips a covenant review.
            if (ds.surplus < this.SURPLUS_FLOOR) {
                ds.covenantBreached = true;
                if (coachKey === `coach_default` || round === 3) coachKey = `coach_breach`;
            }

            ds.diffHistory.push(Math.round(ds.diff));
            ds.rankHistory.push(Math.round(ds.rank));
            ds.balanceHistory.push(Math.round(ds.balance));
            ds.surplusHistory.push(Math.round(ds.surplus * 10) / 10);

            // v1.1.0: persist composite for instructor gradebook (results_utils.php Ruta 1).
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                diff: Math.round(ds.diff),
                diffDelta: Math.round(diffDelta),
                rank: Math.round(ds.rank),
                rankDelta: Math.round(rankDelta),
                surplus: Math.round(ds.surplus * 10) / 10,
                balance: Math.round(ds.balance),
                balanceDelta: Math.round(balanceDelta),
                budgetUsed: ds.budgetUsed,
                covenantBreached: ds.covenantBreached,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(valM) {
            // Locale-aware EUR formatter in millions. EN: €14.0M · ES: 14,0 M€
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const n = Math.round(Number(valM) * 10) / 10;
            if (lang === `es`) {
                return n.toFixed(1).replace(`.`, `,`) + ` M€`;
            }
            return `€` + n.toFixed(1) + `M`;
        }

