            if (ph && phRead) {
                phRead.textContent = ph.value;
                ph.addEventListener(`input`, function() { phRead.textContent = ph.value; });
            }

            // Allocation live total against the EUR 14M cap.
            const allocIds = [`execInput`, `degreeInput`, `facultyInput`, `brandInput`];
            const allocRead = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocRead) allocRead.textContent = self._fmtMoney(total);
                const bar = document.querySelector(`.deanbet-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.ENVELOPE) > 0.001) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

