        _composite(ds) {
            // v1.1.0 single source of truth - verbatim v1.0.0 formula (scoring unchanged).
            const diff = Math.round(ds.diff);
            const rank = Math.round(ds.rank);
            const balance = Math.round(ds.balance);
            const surplus = Math.round(ds.surplus * 10) / 10;
            return Math.round(diff * 0.34 + rank * 0.22 + balance * 0.30 + Math.max(0, Math.min(14, (surplus + 2))) / 14 * 100 * 0.14);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const diff = Math.round(ds.diff);
            const rank = Math.round(ds.rank);
            const balance = Math.round(ds.balance);
            const surplus = Math.round(ds.surplus * 10) / 10;

            const covenantOk = surplus >= this.SURPLUS_FLOOR && !ds.covenantBreached;
            const hitDiff = diff >= this.TARGET_DIFF;
            const hitBalance = balance >= this.TARGET_BALANCE;
            const composite = this._composite(ds);

            let performanceKey = `grade_held`;
            if (!covenantOk) performanceKey = `grade_breach`;
            else if (hitDiff && hitBalance && composite >= 70) performanceKey = `grade_paidoff`;
            else if (hitDiff && hitBalance) performanceKey = `grade_realbet`;
            else if (balance < 35) performanceKey = `grade_thin`;
            else if (ds.armsRace && diff < 40) performanceKey = `grade_armsrace`;
            else if (diff < 35) performanceKey = `grade_eroded`;
            const performance = window.mySimulation.t(performanceKey);
            const met = covenantOk && hitDiff && hitBalance && composite >= 70;

            const insights = [];
            if (!covenantOk) insights.push(window.mySimulation.t(`insight_breach`));
            if (hitDiff && hitBalance && covenantOk) insights.push(window.mySimulation.t(`insight_bet`));
            else if (balance < 35) insights.push(window.mySimulation.t(`insight_thin`));
            else if (ds.armsRace && diff < 40) insights.push(window.mySimulation.t(`insight_armsrace`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (diff < 40) insights.push(window.mySimulation.t(`insight_lowdiff`));
            if (rank >= this.TARGET_RANK && diff < 40) insights.push(window.mySimulation.t(`insight_rankonly`));
            if (hitDiff && hitBalance && covenantOk && surplus >= this.SURPLUS_FLOOR + 0.5) insights.push(window.mySimulation.t(`insight_durable`));

            return {
                diff: diff,
                rank: rank,
                balance: balance,
                surplus: surplus,
                covenantOk: covenantOk,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                hitDiff: hitDiff,
                hitBalance: hitBalance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="deanbet-cm-badge ` + (s.met ? `deanbet-cm-met` : `deanbet-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.covenantOk === false) badges.push(`<span class="deanbet-cm-badge deanbet-cm-fail">` + t(`cm_fail_covenant`) + `</span>`);
            if (s.hitDiff === false) badges.push(`<span class="deanbet-cm-badge deanbet-cm-fail">` + t(`cm_fail_diff`) + `</span>`);
            if (s.hitBalance === false) badges.push(`<span class="deanbet-cm-badge deanbet-cm-fail">` + t(`cm_fail_balance`) + `</span>`);
            const kpi = (label, val) => `<div class="deanbet-cm-metric"><div class="deanbet-cm-metric-val">` + val + `</div><div class="deanbet-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_diff`), (s.diff != null ? Math.round(s.diff) : 0))
                + kpi(t(`cm_rank`), (s.rank != null ? Math.round(s.rank) : 0))
                + kpi(t(`cm_balance`), (s.balance != null ? Math.round(s.balance) : 0))
                + kpi(t(`cm_surplus`), (s.surplus != null ? s.surplus : 0) + `%`)
                + kpi(t(`cm_index`), score + `/100`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="deanbet-cm">`
                + `<div class="deanbet-cm-head"><div class="deanbet-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="deanbet-cm-scorewrap"><span class="deanbet-cm-score">` + score + `</span><span class="deanbet-cm-score-max">/100</span></div>`
                + `<div class="deanbet-cm-grade">` + grade + `</div>`
                + `<div class="deanbet-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="deanbet-cm-metrics">` + kpis + `</div>`
                + `<div class="deanbet-cm-insights"><div class="deanbet-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

