            if (ds.covenantBreached) return window.mySimulation.t(`hint_breach`);
            if (ds.balance < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_thin`);
            if (ds.armsRace && ds.diff < 40) return window.mySimulation.t(`hint_armsrace`);
            if (ds.diff < 35) return window.mySimulation.t(`hint_diff`);
            if (ds.diff >= this.TARGET_DIFF && ds.balance >= this.TARGET_BALANCE) return window.mySimulation.t(`hint_strong`);
            return null;
        }

